"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["2901"],{826(e,n,i){i.r(n),i.d(n,{metadata:()=>o,default:()=>h,frontMatter:()=>a,contentTitle:()=>s,toc:()=>d,assets:()=>l});var o=JSON.parse('{"id":"SoftwareEngineering/modular-monolith","title":"The Modular Monolith","description":"A monolith doesn\'t have to mean tangled, unstructured code. A modular monolith applies the same boundary discipline as microservices \u2014 clear module boundaries, single-responsibility ownership \u2014 while staying a single deployable unit. For most teams, most of the time, this is the right starting point.","source":"@site/docs/SoftwareEngineering/11-modular-monolith.md","sourceDirName":"SoftwareEngineering","slug":"/SoftwareEngineering/modular-monolith","permalink":"/Mindstack/docs/SoftwareEngineering/modular-monolith","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":11,"frontMatter":{"title":"The Modular Monolith","sidebar_label":"Modular Monolith","sidebar_position":11},"sidebar":"softwareEngineeringSidebar","previous":{"title":"Microservices Deep Dive","permalink":"/Mindstack/docs/SoftwareEngineering/microservices-deep-dive"},"next":{"title":"Event-Driven Architecture","permalink":"/Mindstack/docs/SoftwareEngineering/event-driven-architecture"}}'),t=i(4848),r=i(8453);let a={title:"The Modular Monolith",sidebar_label:"Modular Monolith",sidebar_position:11},s="The Modular Monolith",l={},d=[{value:"What Makes a Monolith &quot;Modular&quot;",id:"what-makes-a-monolith-modular",level:2},{value:"Enforcing Module Boundaries",id:"enforcing-module-boundaries",level:2},{value:"Designing Module Boundaries",id:"designing-module-boundaries",level:2},{value:"The Path to Microservices, If You Ever Need It",id:"the-path-to-microservices-if-you-ever-need-it",level:2},{value:"Modular Monolith vs &quot;Just a Monolith&quot;",id:"modular-monolith-vs-just-a-monolith",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function c(e){let n={code:"code",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",ul:"ul",...(0,r.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"the-modular-monolith",children:"The Modular Monolith"})}),"\n",(0,t.jsx)(n.p,{children:"A monolith doesn't have to mean tangled, unstructured code. A modular monolith applies the same boundary discipline as microservices \u2014 clear module boundaries, single-responsibility ownership \u2014 while staying a single deployable unit. For most teams, most of the time, this is the right starting point."}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"what-makes-a-monolith-modular",children:'What Makes a Monolith "Modular"'}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{children:"UNSTRUCTURED MONOLITH (\"Big Ball of Mud\" \u2014 see file 24)\n  \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n  \u2502                                               \u2502\n  \u2502   Everything can call everything.             \u2502\n  \u2502   No enforced boundaries.                     \u2502\n  \u2502   Order code reaches directly into Billing's  \u2502\n  \u2502   internals; Billing reaches into User's.     \u2502\n  \u2502                                               \u2502\n  \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\nMODULAR MONOLITH\n  \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n  \u2502  \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510   \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510   \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510   \u2502\n  \u2502  \u2502  Users   \u2502   \u2502  Orders   \u2502   \u2502Billing  \u2502   \u2502\n  \u2502  \u2502  Module  \u2502   \u2502  Module   \u2502   \u2502Module   \u2502   \u2502\n  \u2502  \u2502          \u2502   \u2502           \u2502   \u2502         \u2502   \u2502\n  \u2502  \u2502 public\u2500\u2500\u2500\u253C\u2500\u2500>\u2502 public\u2500\u2500\u2500\u2500\u253C\u2500\u2500>\u2502public   \u2502   \u2502\n  \u2502  \u2502 API      \u2502   \u2502 API       \u2502   \u2502API      \u2502   \u2502\n  \u2502  \u2502          \u2502   \u2502           \u2502   \u2502         \u2502   \u2502\n  \u2502  \u2502 internals\u2502   \u2502 internals \u2502   \u2502internals\u2502   \u2502\n  \u2502  \u2502 (private)\u2502   \u2502 (private) \u2502   \u2502(private)\u2502   \u2502\n  \u2502  \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518   \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518   \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518   \u2502\n  \u2502                                               \u2502\n  \u2502         ONE deployable process                \u2502\n  \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\nModules communicate ONLY through explicit public interfaces \u2014\nnever by reaching into another module's internals directly. This is\nenforced the same way it would be inside a single microservice's\ncodebase \u2014 the difference is everything still runs in one process,\nso calls are simple function calls, not network requests.\n"})}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"enforcing-module-boundaries",children:"Enforcing Module Boundaries"}),"\n",(0,t.jsx)(n.p,{children:"The boundaries only provide value if something actually enforces them \u2014 \"please don't import from another module's internals\" as a purely social convention tends to erode over time under deadline pressure."}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{className:"language-go",children:"// Go's package system enforces this at compile time (see the Go course's\n// packages-modules page) \u2014 this is one of Go's most useful features\n// for exactly this purpose\n\n// internal/orders/           <- Orders module\n//   order.go                    (contains exported, public API)\n//   internal_calculator.go      (package-private helpers)\n// internal/billing/          <- Billing module\n//   invoice.go\n\n// billing package CANNOT import unexported identifiers from orders \u2014\n// the compiler enforces this. Only orders' explicitly exported\n// (capitalized) functions/types are reachable from outside the package.\n"})}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{className:"language-python",children:'# Python has no compiler-enforced privacy, so boundaries are typically\n# enforced through:\n#   1. Clear directory structure + naming convention (leading underscore\n#      signals "internal, do not import from outside this module")\n#   2. Linting rules (e.g. import-linter) that FAIL CI if a forbidden\n#      cross-module import is detected\n\n# .importlinter config (enforced in CI)\n# [importlinter:contract:1]\n# name = Orders module must not import Billing internals\n# type = forbidden\n# source_modules = myapp.orders\n# forbidden_modules = myapp.billing.internal\n'})}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{children:"Whatever the language, the goal is the same: make a boundary violation\neither impossible (compiler-enforced, as in Go) or immediately visible\nand blocked (linter-enforced in CI, common in Python/JavaScript/Java).\nRelying purely on code review discipline to catch every violation,\nforever, across a growing team, does not scale.\n"})}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"designing-module-boundaries",children:"Designing Module Boundaries"}),"\n",(0,t.jsx)(n.p,{children:"The exact same thinking from file 07 (Bounded Contexts) and file 10 (drawing microservice boundaries) applies here \u2014 a modular monolith's modules are, in effect, microservice boundaries that haven't been split into separate deployments yet."}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{children:'Each module should:\n  Own a specific business capability (Orders, Billing, Inventory \u2014\n  not "Utils" or "Helpers," which aren\'t real capabilities)\n  Own its own data \u2014 even within one shared physical database, each\n  module\'s tables are conceptually "owned" by that module; other\n  modules access that data through the owning module\'s public API,\n  not via a direct query against its tables\n  Expose a small, intentional public API \u2014 everything else is\n  private, hidden implementation detail\n\nA module boundary drawn well here is a module boundary that will\nextract cleanly into a real microservice later, if that ever becomes\nnecessary (see the next section).\n'})}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{className:"language-python",children:"# orders/api.py \u2014 the module's PUBLIC, intentional interface\ndef create_order(customer_id: str, items: list) -> Order:\n    ...\n\ndef get_order(order_id: str) -> Order:\n    ...\n\ndef cancel_order(order_id: str) -> None:\n    ...\n\n# orders/_internal/calculator.py \u2014 private; not part of the public API,\n# not meant to be imported from outside the orders module\ndef _calculate_tax(subtotal, region):\n    ...\n\ndef _apply_discount_rules(order, customer):\n    ...\n"})}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{className:"language-python",children:"# billing/service.py \u2014 another module, consuming Orders THROUGH its\n# public API, never reaching into orders' internals\nfrom orders.api import get_order    # OK \u2014 public API\n# from orders._internal.calculator import _calculate_tax   # FORBIDDEN \u2014\n                                                                # linter blocks this\n\ndef generate_invoice(order_id: str):\n    order = get_order(order_id)     # goes through Orders' public interface\n    ...\n"})}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"the-path-to-microservices-if-you-ever-need-it",children:"The Path to Microservices, If You Ever Need It"}),"\n",(0,t.jsx)(n.p,{children:"This is the practical payoff of doing a modular monolith well: extracting a module into a separate service later becomes a mechanical, low-risk operation instead of an archaeological excavation through tangled code."}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{children:"1. Identify a module with a genuine, demonstrated reason to split out\n   (see file 09's decision framework \u2014 real scaling needs, a team\n   that needs independent deployability, etc.) \u2014 informed by actual\n   operational experience, not a guess made on day one.\n\n2. Because the module already has:\n     - a well-defined public API (no other module reaches into its internals)\n     - its own conceptually-owned data\n   ...the extraction work is largely mechanical:\n     - Stand up a new service exposing the SAME public API, now over\n       the network (HTTP/gRPC) instead of an in-process function call\n     - Migrate the module's data into its own physical database\n     - Replace in-process calls to the module's public API with\n       network calls to the new service (often behind the SAME\n       function signatures, using an adapter \u2014 see the Adapter\n       pattern, file 06 \u2014 so calling code barely changes)\n\n3. The REST of the monolith is unaffected \u2014 you're extracting one\n   well-bounded piece at a time, not doing a risky big-bang rewrite.\n\nThis is precisely why \"start with a modular monolith, extract services\nlater, informed by real needs\" is widely considered lower-risk than\nstarting with microservices from day one (see file 09) \u2014 poor module\nboundaries are cheap to fix within one codebase; poor SERVICE\nboundaries require coordinated cross-team, cross-deployment changes\nplus a live data migration to fix.\n"})}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"modular-monolith-vs-just-a-monolith",children:'Modular Monolith vs "Just a Monolith"'}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{children:'It\'s worth being explicit that these are not the same thing:\n\nUnstructured monolith:\n  Fast to start, but accumulates tangled dependencies over time \u2014\n  the "Big Ball of Mud" anti-pattern (file 24) is the natural\n  end-state without deliberate boundary discipline.\n\nModular monolith:\n  Requires the SAME upfront design thinking as microservices \u2014\n  identifying business capabilities, defining clean public APIs,\n  deciding data ownership \u2014 WITHOUT paying the operational cost of\n  distributed systems (network calls, service discovery, distributed\n  transactions) while that cost isn\'t yet justified.\n\nThe "modular" part is not free \u2014 it requires real discipline and\ndesign effort. The payoff is a system that\'s both easier to work in\nTODAY (clear boundaries, easier to reason about than an unstructured\nmonolith) and cheaper to evolve into microservices LATER, if and when\nthat becomes genuinely necessary.\n'})}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"tips",children:"Tips"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"Enforce module boundaries with tooling (compiler features in Go/Java, linters in Python/JavaScript) \u2014 a boundary that relies purely on developer discipline will erode under deadline pressure, almost without exception."}),"\n",(0,t.jsx)(n.li,{children:"Design each module's public API deliberately and keep it small \u2014 the smaller and more intentional the public surface, the easier both to reason about the module and to extract it into a service later if needed."}),"\n",(0,t.jsx)(n.li,{children:"Give each module conceptual ownership of its own data, even inside one shared physical database \u2014 other modules access that data only through the owning module's public functions, never via a direct query against its tables."}),"\n",(0,t.jsx)(n.li,{children:'Treat "start with a modular monolith" as a genuinely good default for most teams, most of the time \u2014 not merely a stepping stone you\'re obligated to outgrow.'}),"\n"]}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"A modular monolith applies microservice-style boundary discipline (single-responsibility modules, explicit public APIs, owned data) while remaining one deployable unit."}),"\n",(0,t.jsx)(n.li,{children:"Boundaries must be enforced by tooling (compiler privacy in Go, linters in Python/JS) \u2014 social convention alone doesn't hold up over time."}),"\n",(0,t.jsx)(n.li,{children:"Module boundaries should follow business capabilities, the same thinking as Bounded Contexts (file 07) and microservice boundaries (file 10)."}),"\n",(0,t.jsx)(n.li,{children:"A well-bounded module extracts into a real microservice later with mostly mechanical, low-risk work \u2014 because it already has a clean public API and conceptually-owned data."}),"\n",(0,t.jsx)(n.li,{children:'This is why "modular monolith first, extract services later if genuinely needed" (file 09) is widely considered the lower-risk path compared to starting with microservices before the organizational need is demonstrated.'}),"\n"]})]})}function h(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(c,{...e})}):c(e)}},8453(e,n,i){i.d(n,{R:()=>a,x:()=>s});var o=i(6540);let t={},r=o.createContext(t);function a(e){let n=o.useContext(r);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),o.createElement(r.Provider,{value:n},e.children)}}}]);